    let t7 = &c[2][1] - &c[3][1];
    let t8 = &c[2][2] - &c[3][2];
    let t9 = &t4 * &t8;
    let t10 = &t5 * &t7;
    let t11 = &t9 - &t10;
    let t12 = &t5 * &t6;
    let t13 = &t3 * &t8;
    let t14 = &t12 - &t13;
    let t15 = &t3 * &t7;
    let t16 = &t4 * &t6;
    let t17 = &t15 - &t16;
    let t18 = &t1 * &t8;
    let t19 = &t2 * &t7;
    let t20 = &t18 - &t19;
    let t21 = &t2 * &t6;
    let t22 = &t0 * &t8;
    let t23 = &t21 - &t22;
    let t24 = &t0 * &t7;
    let t25 = &t1 * &t6;
    let t26 = &t24 - &t25;
